export const imgUrl = (path) => {
  if (!path || typeof path !== 'string') return '/product-images/placeholder.svg';
  const webpPath = path.replace(/\.(jpg|jpeg|png)$/i, '.webp');
  return `/product-images-optimized/${webpPath}`;
};

